const THEME_KEY="reader_theme",DARK_THEME="dark",LIGHT_THEME="light";class ThemeManager{constructor(){this.currentTheme=this.getSavedTheme(),this.themeToggle=null,this.init()}getSavedTheme(){const e=localStorage.getItem(THEME_KEY);return"dark"===e||"light"===e?e:"light"}init(){this.applyTheme(this.currentTheme),"loading"===document.readyState?document.addEventListener("DOMContentLoaded",()=>this.setupToggle()):this.setupToggle()}applyTheme(e){"dark"===e?document.documentElement.setAttribute("data-theme","dark"):document.documentElement.removeAttribute("data-theme"),this.currentTheme=e,localStorage.setItem(THEME_KEY,e),this.themeToggle&&this.themeToggle.classList.toggle("active","dark"===e)}toggle(){const e="dark"===this.currentTheme?"light":"dark";this.applyTheme(e)}setupToggle(){this.themeToggle=document.getElementById("themeToggle"),this.themeToggle&&(this.themeToggle.classList.toggle("active","dark"===this.currentTheme),this.themeToggle.addEventListener("click",()=>this.toggle()))}getTheme(){return this.currentTheme}isDark(){return"dark"===this.currentTheme}}const themeManager=new ThemeManager;export{themeManager,ThemeManager};"undefined"!=typeof window&&(window.themeManager=themeManager);